from fastapi import APIRouter, Depends, HTTPException, Path
from fastapi.responses import JSONResponse
from starlette.middleware.base import BaseHTTPMiddleware
from services.db import connect
from services.calculations.portfolio import get_portfolio_value, get_gain_loss, get_weight, get_allocation, get_xirr, get_concentration, get_overlap
from services.agents.investment_specialist import HoldingsAnalyzer, QualityChecker, AllocationDrift
from models import Holding, QualityReport, AllocationDriftReport, ResearchReport
from typing import List, Optional

router = APIRouter()

@router.get("/holdings", response_model=List[Holding])
async def get_holdings():
    conn = connect()
    holdings = conn.execute("SELECT * FROM active_holdings").fetchall()
    return [Holding(**row) for row in holdings]

@router.get("/holdings/{id}", response_model=Holding)
async def get_holding(id: int):
    conn = connect()
    holding = conn.execute("SELECT * FROM active_holdings WHERE id = ?", (id,)).fetchone()
    if not holding:
        raise HTTPException(status_code=404, detail="Holding not found")
    return Holding(**holding)

@router.put("/holdings/{id}", response_model=Holding)
async def update_holding(id: int, holding: Holding):
    conn = connect()
    conn.execute("UPDATE active_holdings SET name = ?, units = ?, avg_cost = ? WHERE id = ?", (holding.name, holding.units, holding.avg_cost, id))
    conn.commit()
    return Holding(**holding)

@router.delete("/holdings/{id}", response_model=Holding)
async def delete_holding(id: int):
    conn = connect()
    holding = conn.execute("SELECT * FROM active_holdings WHERE id = ?", (id,)).fetchone()
    if not holding:
        raise HTTPException(status_code=404, detail="Holding not found")
    lots_count = conn.execute("SELECT COUNT(*) FROM lots WHERE holding_id = ?", (id,)).fetchone()[0]
    if lots_count > 0:
        raise HTTPException(status_code=409, detail="Use archive")
    conn.execute("DELETE FROM active_holdings WHERE id = ?", (id,))
    conn.commit()
    return Holding(**holding)

@router.post("/holdings/{id}/archive", response_model=Holding)
async def archive_holding(id: int):
    conn = connect()
    holding = conn.execute("SELECT * FROM active_holdings WHERE id = ?", (id,)).fetchone()
    if not holding:
        raise HTTPException(status_code=404, detail="Holding not found")
    conn.execute("UPDATE active_holdings SET archived_at = CURRENT_TIMESTAMP WHERE id = ?", (id,))
    conn.commit()
    return Holding(**holding)

